/**  `take_notices` has something. */
export type NoticesChanged = null;

/**  The «Обзор» tab, read in one go. */
export type Overview = {
	/**  The active engine's service: `zapret2` once installed (zapret2 spec 3.1). */
	service_name: string,
	service: SvcState,
	windivert: SvcState,
	/**  That service's process: `winws2.exe`. */
	winws_running: boolean,
	strategy: string | null,
	/**  The zapret2 folder and its version, or why it cannot be used. */
	zapret2: Info,
	quick: QuickCheck | null,
	last_run: RunSummary | null,
	testing: boolean,
};

/**  One pass of a strategy in a run with repeats, as measured. */
export type Pass = {
	launch_error: string | null,
	targets: TargetResult[],
	dpi: DpiTargetResult[],
	score: Score,
};

export type Preset = "discord-voice" | "discord" | "cloudflare" | "telegram" | "twitch" | "dbd";

/**
 *  A domain (`discord.com`) or URL (`https://gateway.discord.gg`): where it goes, what the
 *  zapret2 lists and the routing rules think of it, whether it answers through zapret.
 */
export type ProbeResult = {
	host: string,
	url: string,
	resolved_ips: string[],
	matching: Matchings,
	checks: Checks,
	/**
	 *  Packets that went through `queue num 200` while the checks ran (the counters before them
	 *  are subtracted): more than 0 is the site's traffic actually seen by nfqws2. The counter
	 *  sum saturates at 4 billion, which a check of seconds never reaches.
	 */
	intercepted_packets: number | null,
};

/**  A profile as the card and the builder show it. */
export type Profile = {
	/**  From 0, counting every `--new`: what `CircularTarget` names. */
	index: number,
	/**  From 1, as the card numbers profiles; 0 for one with nothing but global options. */
	number: number,
	/**  What the profile matches: every option but the global ones and the desync part. */
	filter: string,
	circular: CircularSettings | null,
	variants: CircularVariant[],
	/**  The instances without `strategy=`, as a variant's text: a plain profile's whole desync. */
	plain: string,
};

export type ProfileScore = {
	ok: number,
	total: number,
	median_ms: number | null,
};

export type Progress = 
/**  Strategy `index` (from 0) of `total` starts, in pass `pass` (from 0) of `passes`. */
{ kind: "Strategy"; index: number; total: number; name: string; pass: number; passes: number } | 
/**  A strategy's passes so far, aggregated (`rank::aggregate`). */
{ kind: "Done"; result: StrategyResult } | { kind: "Restoring" };

export type Protocol = "tcp" | "udp" | "both";

export type ProxiesDiag = {
	socks5: SocksDiag,
	tg_ws: TgWsDiag,
};

export type ProxyState = { state: "Unknown" } | { state: "Ok"; latency_ms: number } | { state: "Down"; error: string } | { state: "AuthRequired" } | { state: "NoUdp" };

export type ProxyStatus = {
	ok: boolean,
	latency_ms: number | null,
	error: string | null,
};

export type QuickCheck = {
	ok: boolean,
	service: SvcState,
	winws_running: boolean,
	checks: QuickItem[],
};

export type QuickItem = {
	name: string,
	status: CheckStatus,
	time_ms: number | null,
};

export type Request = {
	suite: Suite,
	/**  Strategy names, in the order to run them. */
	strategies: string[],
	/**  Passes over the list, `1..=MAX_REPEATS`; a request from before repeats has one. */
	repeats?: number,
};

export type RouterState = { state: "Off" } | { state: "Running" } | { state: "Paused" } | { state: "Unavailable"; reason: string };

export type RouterStatus = {
	state: RouterState,
	proxy: ProxyState,
	totals: Totals,
	rules_error: string | null,
};

export type RoutesView = {
	rules: RuleRow[],
	error: string | null,
	/**
	 *  The system resolves names over encrypted DNS: the sniffer sees no answers and domain
	 *  rules match nothing until an app resolves them in the clear.
	 */
	system_doh: boolean,
};

export type Rule = {
	name: string,
	enabled: boolean,
	protocol: Protocol,
	ports: string[],
	ips: string[],
	domains: string[],
	apps: string[],
};

export type RuleRow = {
	rule: Rule,
	traffic: Traffic,
};

export type RunSummary = {
	id: string,
	suite: Suite,
	canceled: boolean,
	strategies: number,
	/**  The first of the ranking, unless even it failed to start. */
	best: string | null,
	best_score: Score | null,
};

/**
 *  The counts behind the ranking (spec 7.4). A DPI run fills `ok`, `total`, `fail`, `unsup`,
 *  `likely_blocked`.
 */
export type Score = {
	ok: number,
	/**  3 checks per URL target of `targets.txt`: 36 with Flowseal's file. */
	total: number,
	errors: number,
	ssl: number,
	unsup: number,
	/**  Median `time_total` of the checks that passed. */
	median_ms: number | null,
	ping_ok: number,
	ping_total: number,
	ping_median_ms: number | null,
	fail: number,
	likely_blocked: number,
	discord: ProfileScore,
	youtube: ProfileScore,
};

/**  One component of a service (text API, voice, video stream): what answered and what it said. */
export type ServiceComponent = {
	name: string,
	ok: boolean,
	detail: string,
};

export type ServiceDiag = {
	name: string,
	state: SvcState,
	strategy: string | null,
	game_filter: boolean,
};

/**
 *  The deep diagnosis of one service: every component's state and the expert verdict with the
 *  ready advice — what to switch when a component is down.
 */
export type ServiceDiagnosticsReport = {
	service: DiagnosticTarget,
	components: ServiceComponent[],
	verdict: string,
	total_ms: number,
};

export type Settings = {
	/**  The zapret2 folder (zapret2 spec 4); `None` while zapret2 is off. */
	zapret2_dir?: string | null,
	/**  `127.0.0.1:2080`: checked on the overview, used when a download fails directly. */
	socks5?: string | null,
	autostart?: boolean,
	/**  A logon start stays in the tray. */
	start_minimized?: boolean,
	theme?: Theme,
	wizard_done?: boolean,
	/**  The pipe of `zapret-hub-cli` runs commands (CLI spec 5). */
	cli_enabled?: boolean,
	/**  Routing through the SOCKS5 proxy (router spec 3); only `set_router_enabled` writes it. */
	router_enabled?: boolean,
	/**
	 *  The game filter's port placeholder `%GameFilter*`: the whole unprivileged range when on
	 *  (DbD's matchmaking, AWS GameLift), `12` when off.
	 */
	game_filter?: boolean,
	/**
	 *  The exclusions card's ports (`51413`, `6881-6889`): traffic on them leaves the nfqueue;
	 *  the nftables queue is baked with them at every apply (zapret2 spec 5.1).
	 */
	excluded_ports?: string[],
	/**  The `tg-ws-proxy-rs` service: only `set_tg_ws_enabled` writes the flag (tgws spec 2). */
	tg_ws_enabled?: boolean,
	/**  The MTProto port `tg-ws-proxy` listens on. */
	tg_ws_port?: number,
	/**  32 hex characters: the MTProto secret; empty means «generate once» (`tgws::ensure_secret`). */
	tg_ws_secret?: string,
	/**  Extra CLI flags after `--secret`, e.g. `--fronting-domain example.com`. */
	tg_ws_args?: string,
};

export type SocksDiag = {
	/**  The setting holds an address. */
	set: boolean,
	/**  It answered a SOCKS5 greeting now. */
	ok: boolean,
	error: string | null,
};

/**  zapret, the settings or the history changed: the page reads what it shows again. */
export type StateChanged = null;

export type StrategyDetail = {
	row: StrategyRow,
	wf: string,
	blocks: string[],
	/**  `Final args` as the engine reads them. */
	final_args: string | null,
	/**  Every check of the last run the strategy was in. */
	result: StrategyResult | null,
	/**  A zapret2 strategy's text as written, for its editor. */
	source: string,
	/**  A zapret2 strategy's profiles, for its circular ones. */
	circular: Analysis,
};

export type StrategyResult = {
	name: string,
	/**  SHA-256 of the arguments it ran with: once they change, this result is stale. */
	args_sha256: string,
	/**  The file did not parse, winws did not start or exited: the whole output. */
	launch_error: string | null,
	targets: TargetResult[],
	dpi: DpiTargetResult[],
	score: Score,
	/**
	 *  A run with repeats: every pass as it ran; the fields above are then their aggregate
	 *  (`rank::aggregate`). Empty for a single pass and in runs from before repeats.
	 */
	passes?: Pass[],
};

export type StrategyRow = {
	/**  `zapret2:<name>`, or `zapret2:<file>` for a file of the folder that is not a strategy. */
	name: string,
	/**  A strategy of the user's. */
	custom: boolean,
	active: boolean,
	/**  Not readable, named like a built-in one, or not passing the static check of zapret2. */
	error: string | null,
	last: LastResult | null,
};

export type Suite = "Standard" | "Dpi";

export type SvcState = "NotInstalled" | "Stopped" | "StartPending" | "StopPending" | "Running" | "Other";

/**
 *  The system DNS against a public resolver: the resolver of `/etc/resolv.conf` answers, and a
 *  plain UDP query of `DNS_SERVERS` does.
 */
export type SystemDnsDiag = {
	/**  The system resolver answered within the budget. */
	system_ok: boolean,
	/**  Any public resolver answered directly over UDP 53. */
	direct_ok: boolean,
};

export type TargetResult = {
	name: string,
	/**  `None` for a ping-only target. */
	url: string | null,
	/**  A profile host `targets.txt` lacks: shown, never counted (spec 7.4). */
	extra: boolean,
	checks: CheckResult[],
	/**  ICMP round trip; `None` on timeout. */
	ping_ms: number | null,
};

export type TestProgress = Progress;

export type TestRun = {
	/**  `2026-10-10_05-03-34`, also the file name. */
	id: string,
	suite: Suite,
	/**
	 *  `winws2.exe --version` when zapret2 strategies ran: the hash of a command line does not see
	 *  an engine update (zapret2 spec 7). Runs from before zapret2 have none.
	 */
	zapret2_version?: string | null,
	canceled: boolean,
	/**  What could not be put back after the run. */
	restore_error: string | null,
	/**  Best first. */
	strategies: StrategyResult[],
};

/**  The run is over and zapret is back; `run_id` is `None` when it failed before a result. */
export type TestsFinished = {
	run_id: string | null,
};

export type TgWsDiag = {
	installed: boolean,
	/**  `systemctl --user is-active` answers «active». */
	running: boolean,
	/**  The settings' port. */
	port: number,
	/**  A TCP connection to the port got through. */
	listening: boolean,
};

/**  The tg-ws-proxy service: what the overview's and the tools' cards show, read in one go. */
export type TgWsStatus = {
	/**  The static binary is on the disk. */
	installed: boolean,
	/**  The tag from the release `version.txt` keeps next to the binary. */
	version: string | null,
	/**  `systemctl --user is-active` answers «active». */
	running: boolean,
	port: number,
	/**  The 32 hex characters of the MTProto secret (or the empty default before a save). */
	secret: string,
	/**  The extra CLI flags after `--secret`. */
	args: string,
	/**  `tg://proxy?server=127.0.0.1&port=<port>&secret=dd<secret>`. */
	tg_url: string,
	/**  The last lines of the unit's journal. */
	logs: string,
};

export type Theme = "system" | "light" | "dark";

export type Totals = {
	proxied: Traffic,
	direct: Traffic,
};

/**  Bytes are `f64`: specta forbids u64 in TypeScript. */
export type Traffic = {
	flows: number,
	up: number | null,
	down: number | null,
};

export type Via = { via: "Opening" } | { via: "Proxy" } | { via: "Direct"; reason: DirectReason };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

